const m = $json;

function num(s) {
  if (!s) return null;
  // "1.234,56" -> 1234.56   |   "1,234.56" -> 1234.56
  let t = String(s).trim();
  if (/,\d{1,2}$/.test(t)) t = t.replace(/\./g, '').replace(',', '.');
  else t = t.replace(/,/g, '');
  const n = parseFloat(t);
  return isNaN(n) ? null : n;
}

// Ogni estrattore: mittente da riconoscere + funzione che ritorna
// { importo, esercente, tipo } oppure null se il formato non corrisponde.
const ESTRATTORI = [
  {
    nome: 'paypal',
    quando: (e) => e.mittente.includes('paypal'),
    estrai: (e) => {
      const imp = e.testo.match(/(?:EUR|€)\s*([\d.,]+)/i);
      const dest = e.testo.match(/(?:a|to)\s+([A-Z][\w\s.'-]{2,40}?)\s+(?:per|for|EUR|€)/);
      if (!imp) return null;
      return {
        importo: num(imp[1]),
        esercente: (dest?.[1] || 'paypal').toLowerCase().trim(),
        tipo: /hai ricevuto|you received/i.test(e.testo) ? 'entrata' : 'spesa',
      };
    },
  },
];

for (const est of ESTRATTORI) {
  if (!est.quando(m)) continue;
  const r = est.estrai(m);
  if (r && r.importo) {
    return { json: { ...m, ...r, confidenza: 1, serve_ai: false, estrattore: est.nome } };
  }
  // Riconosciuto il mittente ma non il formato: passa all'AI invece di
  // buttare via la mail. I template cambiano senza preavviso.
}

// --- Estrattore generico per bollette e fatture italiane ---
// Ancorato alle parole chiave di totale: e' l'unico modo affidabile di
// distinguere il totale dalle voci di dettaglio senza chiedere a un modello.
const RE_TOTALE = new RegExp(
  '(totale\\s+(?:dovuto|documento|fattura|complessivo)?|importo\\s+(?:totale|da\\s+pagare)' +
  '|totale\\s+da\\s+pagare|da\\s+pagare|addebito(?:\\s+di)?)' +
  '\\s*[:\\-]?\\s*(?:EUR|€)?\\s*([\\d.\\s]*\\d(?:,\\d{2})?)', 'i');

// Tutti gli importi presenti nel testo: serve a sapere se ce n'era uno solo
// (nessuna ambiguita') o molti (voci di dettaglio, IVA, subtotali).
const tuttiImporti = [...m.testo.matchAll(/(?:EUR|€)\s*([\d.]*\d(?:,\d{2})?)|([\d.]*\d,\d{2})\s*(?:EUR|€)/gi)]
  .map(x => num(x[1] || x[2]))
  .filter(v => v && v > 0);

const totale = m.testo.match(RE_TOTALE);

// --- Annuncio o addebito gia' avvenuto? ---
// Le bollette con addebito diretto annunciano un prelievo futuro: registrarle
// come spesa significa contarle due volte quando l'addebito arriva davvero.
const RE_ANNUNCIO = /addebito\s+diretto|\bsdd\b|verr[àa]\s+(?:addebitat|preleva)|sar[àa]\s+addebitat|in\s+scadenz|entro\s+il\s+\d/i;

const RE_SCADENZA = new RegExp(
  '(scadenz\\w*|addebit\\w*|pagamento\\s+previsto|entro\\s+il|verr[àa]\\s+addebitat\\w*)' +
  '[^\\d]{0,40}(\\d{1,2}[\\/\\-.]\\d{1,2}[\\/\\-.]\\d{2,4})', 'i');

function dataISO(s) {
  if (!s) return null;
  s = String(s).trim();
  let x = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (x) return `${x[1]}-${x[2]}-${x[3]}`;
  x = s.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!x) return null;
  let [, g, me, a] = x;
  if (a.length === 2) a = '20' + a;
  return `${a}-${me.padStart(2, '0')}-${g.padStart(2, '0')}`;
}

const scad = m.testo.match(RE_SCADENZA);

return { json: {
  ...m,
  serve_ai: true,
  // Suggerimenti passati a Gemini e usati per calibrare la fiducia.
  totale_ancorato: totale ? num(totale[2]) : null,
  sembra_annuncio: RE_ANNUNCIO.test(m.testo),
  scadenza_ancorata: scad ? dataISO(scad[2]) : null,
  importi_trovati: [...new Set(tuttiImporti)],
}};

function normalizza(s) {
  if (!s) return '';
  return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

function hash64(str) {
  let h = 0xcbf29ce484222325n;
  const p = 0x100000001b3n;
  for (let i = 0; i < str.length; i++) {
    h ^= BigInt(str.charCodeAt(i));
    h = (h * p) & 0xffffffffffffffffn;
  }
  return h.toString(16).padStart(16, '0');
}

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

function dataISO(s) {
  if (!s) return null;
  s = String(s).trim();
  let x = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (x) return `${x[1]}-${x[2]}-${x[3]}`;
  x = s.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!x) return null;
  let [, g, me, a] = x;
  if (a.length === 2) a = '20' + a;
  return `${a}-${me.padStart(2, '0')}-${g.padStart(2, '0')}`;
}

// Giorno di calendario a Roma: una mail delle 00:30 non deve finire sul
// giorno prima solo perche' il timestamp e' in UTC.
function giornoRoma(s) {
  const t = String(s || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(t)) return t;
  const d = new Date(t);
  if (isNaN(d.getTime())) return t.slice(0, 10);
  return d.toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' });
}

// Un messaggio che non e' una transazione NON deve far restituire una lista
// vuota: il chiamante non vedrebbe nessun output e non marcherebbe la mail
// come lavorata (etichetta Gmail / cartella Outlook).
const ignora = (motivo) => [{ json: { esito: 'ignora', motivo } }];

const m = $('Estrattori').first().json;
let dati = { ...m };

if (!m.importo) {
  const risposta = $('Gemini').first().json;
  const parts = risposta?.candidates?.[0]?.content?.parts || [];
  const testo = parts.map(p => p.text).filter(Boolean).join('')
    .replace(/```json|```/g, '').trim();

  if (!testo) {
    throw new Error('Gemini non ha restituito testo: ' + JSON.stringify(risposta).slice(0, 300));
  }

  let p;
  try {
    p = JSON.parse(testo);
  } catch (e) {
    throw new Error('JSON non parsabile da Gemini: ' + testo.slice(0, 300));
  }

  if (!p.e_transazione) return ignora('non e una transazione');   // corretto uscire

  dati = { ...m, ...p, confidenza: Number(p.confidenza) || 0.5 };
}

if (!dati.importo || dati.importo <= 0) return ignora('importo mancante o non valido');

let confidenza = Number(dati.confidenza || 0.5);
let avviso = '';

const nota = (t) => { avviso = avviso ? avviso + ' — ' + t : t; };

// --- Plausibilita' dell'importo ---
// Se nel testo c'erano piu' cifre e quella scelta non coincide col totale
// ancorato a parola chiave, la fiducia scende e la riga nasce da verificare.
const alternativi = (m.importi_trovati || []).filter(v => v !== Number(dati.importo));

if (m.totale_ancorato && Number(dati.importo) !== m.totale_ancorato) {
  confidenza = Math.min(confidenza, 0.5);
  nota('il testo indicava come totale ' + m.totale_ancorato);
} else if (alternativi.length > 0 && !m.totale_ancorato) {
  confidenza = Math.min(confidenza, 0.6);
  nota('altri importi nel testo: ' + alternativi.slice(0, 5).join(', '));
}

// --- Regole apprese ---
// Quelle create dal bot Telegram quando confermi una categoria: gratis e
// istantanee, valgono anche per mail e push. Una regola vince su Gemini solo
// se la sua categoria esiste ancora fra quelle ammesse.
const ammesse = $('Prepara').first().json.categorie || [];
const regole = $('Leggi Regole').all().map(i => i.json)
  .filter(r => r && r.pattern && normalizza(r.pattern).length >= 2);
const testoRegole = normalizza((dati.esercente || '') + ' ' + (dati.oggetto || ''));
const regola = regole.find(r => testoRegole.includes(normalizza(r.pattern)));
const catRegola = regola
  ? ammesse.find(c => normalizza(c) === normalizza(regola.categoria))
  : null;

// --- Validita' della categoria ---
// Le categorie sono fisse: quelle della tabella, nessuna in piu'. Gemini
// propone, qui si verifica. Il confronto normalizzato perdona maiuscole e
// accenti e riconduce al nome esatto della tabella.
const trovata = catRegola || ammesse.find(c => normalizza(c) === normalizza(dati.categoria));
const categoria = trovata || '';

if (!trovata) {
  confidenza = Math.min(confidenza, 0.3);
  nota('categoria non valida: "' + (dati.categoria || 'vuota') + '"');
} else if (catRegola && !avviso) {
  // La categoria e' certa; resta incerto soltanto cio' che ha segnalato un avviso.
  confidenza = Math.max(confidenza, 0.9);
}

const daVerificare = confidenza < 0.75;

// --- Momento: addebito avvenuto o soltanto annunciato? ---
// Il modello propone, il codice verifica: un annuncio senza una data futura
// non è un annuncio. È la stessa logica applicata alla categoria, dove la
// proposta viene confrontata con l'elenco reale.
const dataMsg = giornoRoma(dati.data);
const prev = dataISO(dati.data_prevista) || m.scadenza_ancorata || null;
const annuncio = dati.momento === 'annuncio' && !!prev && prev > dataMsg;

if (dati.momento === 'annuncio' && !annuncio) {
  nota('dichiarato annuncio ma senza data futura: registrato come addebito');
}

// Un'attesa vale alla data prevista, un addebito a quella del messaggio.
const data = annuncio ? prev : dataMsg;

const esercente = normalizza(dati.esercente);

const conto = /paypal/.test(m.mittente) ? 'paypal'
            : /satispay/.test(m.mittente) ? 'satispay'
            : /revolut/.test(m.mittente) ? 'revolut'
            : 'banca';

// Calcolato dopo che la data è definitiva, altrimenti per le attese l'hash
// descriverebbe un giorno diverso da quello scritto nella riga.
const hash = hash64([data, Number(dati.importo).toFixed(2), esercente,
                     conto, m.id_esterno].join('|'));

const statoRiga = annuncio ? 'attesa'
                : daVerificare ? 'da_verificare'
                : 'confermata';

return [{ json: {
  riga: {
    id: uuid(),
    data_evento: data,
    data_inserimento: new Date().toISOString(),
    fonte: m.fonte,
    tipo: dati.tipo || 'spesa',
    importo: Number(dati.importo).toFixed(2),
    valuta: 'EUR',
    conto,
    esercente,
    categoria,
    sottocategoria: '',
    note: dati.oggetto || '',
    testo_grezzo: (m.mittente + ' | ' + m.oggetto).slice(0, 500),
    hash_dedup: hash,
    confidenza: confidenza.toFixed(2),
    stato: statoRiga,
  },
  avviso,
  regola: catRegola
    ? { pattern: String(regola.pattern), utilizzi: Number(regola.utilizzi) || 0 }
    : null,
}}];

const m = $('Estrattori').first().json;

const categorie = $('Leggi Categorie').all()
  .map(i => i.json.categoria)
  .filter(Boolean);

let prompt = 'Da questa email estrai la transazione finanziaria, se c\'è.\n\n' +
  'Categorie ammesse:\n' + categorie.join('\n') + '\n\n' +
  'Mittente: ' + m.mittente + '\n' +
  'Oggetto: ' + m.oggetto + '\n' +
  'Testo: ' + m.testo + '\n\n';

if ((m.importi_trovati || []).length > 1) {
  prompt += 'ATTENZIONE: nel testo compaiono più importi (' +
    m.importi_trovati.join(', ') + '). Sono voci di dettaglio, imponibile, IVA ' +
    'o subtotali. Restituisci SOLO il totale effettivamente addebitato.\n';
}
if (m.totale_ancorato) {
  prompt += 'Totale ancorato a parola chiave: ' + m.totale_ancorato +
    '. Usalo salvo evidenza contraria.\n';
}

prompt += '\nRispondi solo con JSON: {"e_transazione": true|false, "importo": <numero>, "esercente": "<chi>", "tipo": "spesa"|"entrata", "categoria": "<una>", "momento": "annuncio"|"addebito", "data_prevista": "YYYY-MM-DD"|null, "confidenza": <0.0-1.0>}\n' +
  'Regole:\n' +
    '- momento "addebito" se l operazione e gia avvenuta: pagamenti con carta, notifiche bancarie, ricevute di acquisto. E il caso normale.\n'+
    '- momento "annuncio" se il testo comunica che un importo VERRA addebitato o scade in futuro (bollette con addebito diretto, fatture con scadenza).\n'+
      '- data_prevista solo per gli annunci: la data in cui avverra l addebito.\n'+
  '- e_transazione false per newsletter, promozioni, avvisi di sicurezza.\n' +
  '- e_transazione false per i riepiloghi con più movimenti distinti.\n' +
  '- importo = il totale pagato, mai una singola voce di dettaglio.\n' +
  '- confidenza bassa se non sei sicuro di quale sia il totale.';

const body = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json' },
};

return [{ json: { ...m, categorie, body_json: JSON.stringify(body) } }];
